package com.vaijunto.dto;
import com.vaijunto.domain.entities.Conversation; import java.time.OffsetDateTime; import java.util.UUID;
public record ConversationDto(UUID id,String type,String title,boolean archived,boolean readOnly,OffsetDateTime lastActivityAt) { public static ConversationDto from(Conversation c, UUID userId) { var other=c.getParticipantA()!=null&&c.getParticipantA().getId().equals(userId)?c.getParticipantB():c.getParticipantA(); String title=other==null ? ("OFFICIAL".equals(c.getType())?"VaiJunto":"Atendimento") : other.getName(); return new ConversationDto(c.getId(),c.getType(),title,c.getArchivedAt()!=null,c.getReadOnlyAt()!=null,c.getLastActivityAt()); } }
